-- B1 base-role permissions (PLAN B1 section 3). 0007 seeded the release A sets and cannot change; this brings the
-- three roles B1 extends to BASE_ROLES. Generated by renderBaseRoleUpdate(B1_UPDATED_BASE_ROLES) in
-- apps/api/src/lib/permissions.ts; apps/api/src/lib/permissions.test.ts fails if this block and the catalogue differ.
UPDATE role SET permissions = '{user.manage,settings.manage,import.manage,mapping.edit,mapping.approve,compliance.read,audit.read,vendor_access.decide,market.manage,integration.manage}'::text[] WHERE is_base AND tenant_id IS NULL AND name = 'Tenant admin';
UPDATE role SET permissions = '{compliance.read,participant.unmask,plan.activate,settings.approve}'::text[] WHERE is_base AND tenant_id IS NULL AND name = 'Finance approver';
UPDATE role SET permissions = '{mapping.approve,compliance.read,snapshot.create,export,audit.read,market.signoff}'::text[] WHERE is_base AND tenant_id IS NULL AND name = 'Compliance officer';
